  ui_story_5088_50881201_35_dialog_content = "คุณมาจากที่ไหน?! คุณกำลังพยายามทำอะไร?",
  ui_story_5088_50881201_36_dialog_content = "\"เรา\"? ฮ่า! เราได้เดินทางผ่านสองพันปี—",
