  ui_story_5088_50881201_38_dialog_content = "ปาฏิหาริย์ที่เกิดจากความสัมพันธ์ที่ลึกซึ้งที่สุด!",
  ui_story_5088_50881201_39_dialog_content = "คนอย่างคุณ ที่แต่ปลุกปั่นความขัดแย้งและขัดขวางความผูกพันที่มาจากใจ...",
  ui_story_5088_50881201_40_dialog_content = "เธอจะเข้าใจได้ยังไงล่ะ?!",
  ui_story_5088_50881201_41_dialog_content = "อคิลลีส! คุณนอนพอแล้ว! ตื่นนอน!!!",
  ui_story_5088_50881201_42_dialog_content = "... ลูดวีส?",
