  ui_story_5088_50881201_44_dialog_content = "ระวังนะ มันจะโจมตีแล้ว!",
  ui_story_5088_50881201_45_dialog_content = "ให้ฉันคุ้มครองการป้องกัน!",
  ui_story_5088_50881201_46_dialog_content = "คนทรยศน้อย คุณคิดว่าพวกเขาจะปกป้องคุณได้จริงๆหรือ? คุณอ่อนแอเกินไป...",
  ui_story_5088_50881201_47_dialog_content = "น้องชายจากอนาคต!",
  ui_story_5088_50881201_48_dialog_content = "คุณเคยบอกฉันว่าคุณเชื่อว่าความทรงจำเป็นคำสาป",
  ui_story_5088_50881201_49_dialog_content = "แต่หลังจากที่ฉันใช้ชีวิตมานาน ฉันมีสิ่งที่จะแบ่งปันกับคุณ",
  ui_story_5088_50881201_50_dialog_content = "สำหรับฉัน <color=#FFB400>ความทรงจำคือของขวัญ</color>! คุณได้รับของขวัญมากมาย และคุณได้ยกย่องความคิดเห็นนั้นอย่างมาก นั่นเป็นสิ่งที่น่าประทับใจจริง ๆ",
  ui_story_5088_50881201_51_dialog_content = "นั่นสินะ",
  ui_story_5088_50881201_52_dialog_content = "คุณได้รับมรดกความทรงจำและความมุ่งมั่นของเรา และคุณได้มาถึงที่นี่ สิ่งนั้นเองก็ทำให้ประทับใจมากแล้ว",
  ui_story_5088_50881201_53_dialog_content = "การกระทำของคุณพิสูจน์ว่า ไฟแห่งวีรกรรมสามารถถูกส่งต่อจากยุคหนึ่งไปยุคหนึ่งได้",
  ui_story_5088_50881201_54_dialog_content = "ตอนนี้ ได้เวลาแล้วสำหรับฮีโร่ของยุคเก่าที่จะรู้สึกถึงความสุขของพวกเขา",
