  ui_story_5088_50881202_24_dialog_content = "หลังจากที่รูปแบบเวทมนตร์ด้านนอกหายไป ลูกเล็กเด็กแดงที่อยู่ใกล้ ๆ ก็เริ่มคลานเข้ามาด้วยความอยากรู้อยากเห็น",
  ui_story_5088_50881202_25_dialog_content = "นักรบดวงดาวได้ออกเดินทางเพื่อรักษาความปลอดภัยของพวกเขา",
